package com.dy.artisan3d.ui.componentimport androidx.compose.runtime.Composableimport androidx.compose.ui.Modifierimport androidx.compose.runtime.*import androidx.compose.ui.interop.UIKitViewimport kotlinx.cinterop.ExperimentalForeignApiimport platform.SceneKit.*import platform.Foundation.*import platform.UIKit.*import platform.ModelIO.*@OptIn(ExperimentalForeignApi::class)@Composableactual fun ModelViewer(    modelUrl: String,    modifier: Modifier,    autoRotate: Boolean,    enableZoom: Boolean,    enablePan: Boolean,    onLoaded: () -> Unit,    onError: (String) -> Unit,) {    val scnView = remember { SCNView() }    UIKitView(        factory = {            scnView.apply {                backgroundColor = UIColor.clearColor                allowsCameraControl = true                autoenablesDefaultLighting = true                // Internetdan yuklash uchun URL                val url = NSURL.URLWithString(modelUrl)                if (url != null) {                    // ModelIO orqali GLB-ni yuklash                    val asset = MDLAsset(uRL = url)                    // Asset yuklanganini tekshirish                    if (asset.count() > 0u) {                        // MDLAsset-ni SCNScene-ga o'tkazish                        val scene = SCNScene.sceneWithMDLAsset(asset)                        this.scene = scene                        if (autoRotate) {                            val action = SCNAction.repeatActionForever(                                SCNAction.rotateByX(0.0, 1.0, 0.0, 2.0)                            )                            scene.rootNode.runAction(action)                        }                        onLoaded()                    } else {                        onError("GLB model yuklanmadi yoki format xato")                    }                } else {                    onError("URL xato")                }            }            scnView        },        modifier = modifier,        update = { view ->            view.allowsCameraControl = enableZoom || enablePan        }    )}actual fun isModelViewerSupported(): Boolean = trueactual fun getSupportedModelFormats(): List<String> = listOf("glb", "gltf", "usdz", "obj")